const fs = require('fs');
const path = require('path');

const libDir = 'packages/web-core/src/shared/lib';
const files = fs.readdirSync(libDir).filter(f => f.endsWith('.ts') || f.endsWith('.tsx'));

const exports = {};

files.forEach(file => {
  const content = fs.readFileSync(path.join(libDir, file), 'utf-8');
  const lines = content.split('\n');

  lines.forEach((line, idx) => {
    // Match export function, export const, export async function
    const match = line.match(/^export\s+(async\s+)?function\s+(\w+)|^export\s+const\s+(\w+)\s*=|^export\s+const\s+(\w+)\s*:/);
    if (match) {
      const name = match[2] || match[3] || match[4];
      if (name && !name.match(/^[A-Z]/)) { // Skip types/interfaces/classes
        if (!exports[name]) exports[name] = [];
        exports[name].push(file);
      }
    }
  });
});

Object.entries(exports).forEach(([name, files]) => {
  console.log(`${name}\t${files.join(',')}`);
});
EOF
